sel_in_n = emask_n & (dst_all == GI)
sel_in_wA = emask_wA & (dst_all == GI)
assert int(sel_in_n.sum()) == 13 and int(sel_in_wA.sum()) == 13

T70 = np.zeros(Nall, bool)
